//! Persisted source identity, shared by capture and projection.
use crate::errors::{AppError, Result};
use serde_json::Value;
use std::collections::BTreeMap;
use ubu_store::models::object_record::ObjectRecord;

pub async fn by_source(pool: &sqlx::SqlitePool) -> Result<BTreeMap<String, (ObjectRecord, Value)>> {
    let rows = sqlx::query_as::<_, ObjectRecord>("SELECT * FROM objects WHERE object_type='Task' AND json_extract(payload_json, '$.provenance.source.source_kind')='google_calendar' ORDER BY id")
        .fetch_all(pool).await.map_err(|e| AppError::Internal(e.to_string()))?;
    let mut sources = BTreeMap::new();
    for row in rows {
        let payload: Value = serde_json::from_str(&row.payload_json)
            .map_err(|e| AppError::Internal(e.to_string()))?;
        let source = payload["provenance"]["source"]["source_id"]
            .as_str()
            .ok_or_else(|| AppError::Internal("Calendar source has no source_id".into()))?
            .to_owned();
        if sources.insert(source, (row, payload)).is_some() {
            return Err(AppError::Internal(
                "duplicate Calendar source identity".into(),
            ));
        }
    }
    Ok(sources)
}

pub async fn origins_by_task(pool: &sqlx::SqlitePool) -> Result<BTreeMap<String, String>> {
    Ok(by_source(pool)
        .await?
        .into_iter()
        .map(|(source, (row, _))| (row.id, source))
        .collect())
}

//! Pure Google Calendar request, response and status policy. No transport types.
use serde::Serialize;
use serde_json::Value;
use std::collections::BTreeSet;

use super::calendar_projection::DesiredEvent;

pub const CALENDAR_SCOPE: &str = "https://www.googleapis.com/auth/calendar";
pub const CALENDAR_API_BASE: &str = "https://www.googleapis.com/calendar/v3/calendars";
/// The private extended property UbU writes on an event it creates.
pub const UBU_TASK_PROPERTY: &str = "ubu_task";

// Field order and omission rules match quick-ubu/gcal's GoogleEventBody.
#[derive(Debug, Serialize)]
pub struct GoogleEventBody {
    pub summary: String,
    pub start: GoogleEventTime,
    pub end: GoogleEventTime,
    #[serde(rename = "colorId", skip_serializing_if = "Option::is_none")]
    pub color_id: Option<String>,
    pub transparency: String,
    pub reminders: GoogleReminders,
}

#[derive(Debug, Serialize)]
pub struct GoogleReminders {
    #[serde(rename = "useDefault")]
    pub use_default: bool,
    pub overrides: Vec<GoogleReminder>,
}

#[derive(Debug, Serialize)]
pub struct GoogleReminder {
    pub method: &'static str,
    // DesiredEvent uses i64; preserve it without narrowing or truncation.
    pub minutes: i64,
}

#[derive(Debug, Serialize)]
pub struct GoogleEventTime {
    #[serde(rename = "dateTime")]
    pub date_time: String,
}

pub fn event_body(event: &DesiredEvent) -> GoogleEventBody {
    GoogleEventBody {
        summary: event.summary.clone(),
        start: GoogleEventTime {
            date_time: event.start_at.clone(),
        },
        end: GoogleEventTime {
            date_time: event.end_at.clone(),
        },
        color_id: event.color_id.clone(),
        transparency: if event.transparent {
            "transparent"
        } else {
            "opaque"
        }
        .into(),
        reminders: GoogleReminders {
            use_default: false,
            overrides: event
                .reminders_minutes
                .iter()
                .map(|&minutes| GoogleReminder {
                    method: "popup",
                    minutes,
                })
                .collect(),
        },
    }
}

fn required_string<'a>(value: &'a Value, field: &str) -> Result<&'a str, String> {
    value
        .get(field)
        .and_then(Value::as_str)
        .ok_or_else(|| format!("missing or invalid {field}"))
}

/// An all-day event has a date and no time, so it has no length. It cannot be a
/// Dynamic Task without inventing a duration, and a commitment with no time has
/// no window to pin. It is skipped, and the message says why.
pub const ALL_DAY_MESSAGE: &str = "all-day event has no dateTime; it carries no duration, so it cannot be scheduled and is skipped";

pub fn parse_event(value: &Value) -> Result<DesiredEvent, String> {
    parse_event_with_diagnostic(value).map(|(event, _)| event)
}

pub const DESCRIPTION_TOO_LARGE_CODE: &str = "capture_description_too_large";

fn description_limit_message() -> String {
    format!("description exceeds {} bytes; notes were not imported, but the event remains available for capture", super::clarify::MAX_DESCRIPTION_BYTES)
}

/// The same policy for Google input, normalized mock input and capture planning.
/// Whitespace is trimmed; markup and interior text are otherwise untouched.
pub fn capture_description(id: &str, raw: Option<&str>) -> (Option<String>, Option<String>) {
    let Some(text) = raw.map(str::trim).filter(|text| !text.is_empty()) else {
        return (None, None);
    };
    if text.len() > super::clarify::MAX_DESCRIPTION_BYTES {
        return (None, Some(format!("Calendar event `{id}`: {}", description_limit_message())));
    }
    (Some(text.to_owned()), None)
}

pub fn parse_event_with_diagnostic(value: &Value) -> Result<(DesiredEvent, Option<String>), String> {
    if value.get("status").and_then(Value::as_str) == Some("cancelled") {
        return Err("cancelled event".into());
    }
    let id = required_string(value, "id")?;
    let task_id = format!("task_{id}");
    let summary = required_string(value, "summary")?;
    let raw_description = match value.get("description") {
        None => None,
        Some(Value::String(text)) => Some(text.as_str()),
        _ => return Err("invalid description".into()),
    };
    let (description, description_diagnostic) = capture_description(id, raw_description);
    if value["start"].get("date").is_some() && value["start"].get("dateTime").is_none() {
        return Err(ALL_DAY_MESSAGE.into());
    }
    let start_at = required_string(&value["start"], "dateTime")?;
    let end_at = required_string(&value["end"], "dateTime")?;
    let start =
        chrono::DateTime::parse_from_rfc3339(start_at).map_err(|_| "invalid start.dateTime")?;
    let end = chrono::DateTime::parse_from_rfc3339(end_at).map_err(|_| "invalid end.dateTime")?;
    if end <= start {
        return Err("end.dateTime must follow start.dateTime".into());
    }
    let color_id = match value.get("colorId") {
        None => None,
        Some(Value::String(color)) => Some(color.clone()),
        _ => return Err("invalid colorId".into()),
    };
    // Like Quick UbU, an absent transparency means opaque.
    let transparent = match value.get("transparency") {
        None => false,
        Some(Value::String(transparency)) => transparency == "transparent",
        _ => return Err("invalid transparency".into()),
    };
    let reminders = &value["reminders"];
    // Default reminders are Calendar settings, not Task metadata. No explicit
    // reminder can be recovered from an omitted/default reminder specification.
    let explicit = match reminders.get("useDefault") {
        Some(Value::Bool(false)) => reminders.get("overrides"),
        Some(Value::Bool(true)) => None,
        None if reminders.is_null() => None,
        _ => return Err("invalid reminders.useDefault".into()),
    };
    let overrides = match explicit {
        None => &[][..], // Google may omit an empty overrides array.
        Some(Value::Array(overrides)) => overrides.as_slice(),
        _ => return Err("invalid reminders.overrides".into()),
    };
    let reminders_minutes = overrides
        .iter()
        .map(|reminder| {
            if reminder["method"] != "popup" {
                return Err("unsupported reminder method".into());
            }
            reminder["minutes"]
                .as_i64()
                .filter(|minutes| *minutes >= 0)
                .ok_or_else(|| "invalid reminder minutes".into())
        })
        .collect::<Result<Vec<_>, String>>()?;
    Ok((DesiredEvent {
        external_id: id.into(),
        task_id,
        summary: summary.into(),
        description,
        start_at: start_at.into(),
        end_at: end_at.into(),
        color_id,
        transparent,
        reminders_minutes,
    }, description_diagnostic))
}

pub fn parse_event_list(value: &Value) -> (Vec<DesiredEvent>, Vec<String>) {
    let Some(items) = value.get("items").and_then(Value::as_array) else {
        return (
            Vec::new(),
            vec!["list event `*`: missing or invalid items".into()],
        );
    };
    let mut events = Vec::new();
    let mut messages = Vec::new();
    for (index, item) in items.iter().enumerate() {
        match parse_event_with_diagnostic(item) {
            Ok((event, diagnostic)) => {
                events.push(event);
                messages.extend(diagnostic);
            }
            // Identify the entry by index and readable handle, never by its title or content.
            Err(message) => {
                let id = item.get("id").and_then(Value::as_str).unwrap_or("*");
                messages.push(format!("list event `{id}` entry {index}: {message}"));
            }
        }
    }
    (events, messages)
}

/// Ids of listed events UbU minted itself: the stamp is present and names the Task
/// whose handle the event id is. An event UbU only patched carries no stamp, and a
/// stamp that does not match the id is not evidence of minting.
///
/// Every absence yields fewer ids and never a failure: no `items`, no
/// `extendedProperties`, a `private` that is not an object, a stamp that is not a
/// string. `parse_event_list` reads the same JSON for the events themselves; this is
/// a second pass over it for where they came from.
pub fn ubu_created_ids(value: &Value) -> BTreeSet<String> {
    value
        .get("items")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|item| {
            let id = item.get("id")?.as_str()?;
            let stamp = item
                .get("extendedProperties")?
                .get("private")?
                .get(UBU_TASK_PROPERTY)?
                .as_str()?;
            (stamp == format!("task_{id}")).then(|| id.to_owned())
        })
        .collect()
}

pub fn list_diagnostic(message: String) -> crate::api::planning::DiagnosticBody {
    crate::api::planning::DiagnosticBody {

    #[serde(default)]
    out_of_range_events: Vec<DesiredEvent>,
}

fn internal(error: impl std::fmt::Display) -> AppError {
    AppError::Internal(error.to_string())
}

pub async fn reconcile(
    state: &AppState,
    mode: CalendarExportMode,
) -> Result<CalendarReconcileResponse> {
    mode.ensure_available(state)?;
    let _guard = state.inner().calendar_projection_lock.lock().await;
    let pool = state.inner().store.pool();
    let applied = calendar_apply::last_applied_events(pool).await?;
    // Match last_applied_events' schema/status/order exactly for source links.
    let previous = sqlx::query("SELECT id, preview_id FROM projection_results WHERE status IN ('applied','partial') AND json_extract(payload_json,'$.schema_version')=? ORDER BY rowid DESC LIMIT 1")
        .bind(CALENDAR_PROJECTION_RESULT_SCHEMA_VERSION).fetch_optional(pool).await.map_err(internal)?;
    let result_id: Option<String> = previous
        .as_ref()
        .map(|row| row.try_get("id"))
        .transpose()
        .map_err(internal)?;
    // Before the first apply there is no source preview. Reserve a correctly
    // typed bookkeeping id for the existing NOT NULL preview_id columns; this
    // does not create a preview, invent ownership, or claim a prior delivery.
    let preview_id: String = previous
        .as_ref()
        .map(|row| row.try_get("preview_id"))
        .transpose()
        .map_err(internal)?
        .unwrap_or_else(|| UbuId::new(ObjectType::ProjectionPreview).to_string());
    let google = if mode == CalendarExportMode::Live {
        Some(Arc::new(
            GoogleCalendarApi::new(&state.inner().config).map_err(internal)?,
        ))
    } else {
        None
    };
    let client: Arc<dyn CalendarApi> = match &google {
        Some(client) => client.clone(),
        None => state.mock_calendar_api(&applied),
    };
    let range = super::calendar_range::CalendarTimeRange::planning(state).await?;
    let (applied, out_of_range_events): (Vec<_>, Vec<_>) = applied.into_iter().partition(|event| range.overlaps(event));
    let mut observed = client.list_events(&range).await.map_err(AppError::Upstream)?;
    super::calendar_capture::normalize_observed(&mut observed, &applied);
    let ubu_created_ids = client.take_ubu_created_ids().await;
    let mut diagnostics = client.take_diagnostics().await;
    for (source, (row, payload)) in super::calendar_sources::by_source(pool).await? {
        if row.status != "active" || observed.iter().any(|event| event.external_id == source) { continue; }
        // A bounded observation says nothing about commitments outside its range.
        let in_range = payload["static_window"]["start"].as_str().zip(payload["static_window"]["end"].as_str())
            .and_then(|(start,end)| super::calendar_range::CalendarTimeRange::parse(start,end).ok())
            .is_some_and(|window| window.start < range.end && window.end > range.start);
        if in_range {
            diagnostics.push(crate::api::planning::DiagnosticBody {
                code: "capture_source_removed".into(),
                message: format!("Captured Task `{}` has no source event in the observed planning horizon; Task retained for operator review", row.id),
            });
        }
    }
    let known = known_external_ids(pool).await?;
    let conflicts = calendar_reconcile::classify(&applied, &observed, &known, &ubu_created_ids);
    // Carry the capture refusal through the existing diagnostic contract. The UI
    // groups by this backend reason rather than duplicating the ownership rule.
    diagnostics.extend(conflicts.iter()
        .filter(|conflict| conflict.conflict_type == "foreign")
        .filter_map(|conflict| super::calendar_capture::not_ownable_diagnostic(&conflict.external_id)));
    let status = if conflicts.is_empty() {

                response.skipped += 1;
                diagnostics.push(DiagnosticBody {
                    code: "capture_unrecorded_event".into(),
                    message: format!("Event `{}` matches known Task evidence without applied ownership; not captured", event.external_id),
                });
            }
        }
    }
    let now = state.planning_now();
    let mut recorded = !interaction.changed_external_ids.is_empty();
    for task in tasks {
        let previous = existing.get(&task.origin_event_id);
        if previous.is_some_and(|(row, _)| row.status != "active") {
            response.skipped += 1;
            continue;
        }
        let id = match &task.task_id {
            Some(id) => UbuId::parse(id).map_err(internal)?,
            None => UbuId::new(ObjectType::Task),
        };
        let mut payload = previous.map(|(_,payload)| payload.clone()).unwrap_or_else(|| json!({
            "id":id, "status":"active", "provenance":{"created_at":now,"authority_source":"user","source":{"source_kind":"google_calendar","source_id":task.origin_event_id}}
        }));
        payload["title"] = task.title.clone().into();
        // Calendar notes may fill a blank, never replace authored or interviewed text.
        if payload.get("description").and_then(serde_json::Value::as_str).is_none_or(|text| text.trim().is_empty()) {
            if let Some(description) = &task.description {
                payload["description"] = description.clone().into();
            }
        }
        // One scheduling form, never both. A Task that changes placement loses
        // the other form's field rather than keeping a stale one.
        let fields = payload.as_object_mut().unwrap();
        match task.placement {
            CapturedPlacement::Static => {
                if fields.get("static_window").is_none_or(|window| window.is_null()) {
                    fields.remove("duration_estimate");
                }
                fields.insert("static_window".into(), json!({"start":task.start_at,"end":task.end_at}));
            }
            CapturedPlacement::Dynamic { seconds } => {
                fields.remove("static_window");
                fields.insert("duration_estimate".into(), json!({"type":"fixed","seconds":seconds}));
            }
        }
        payload["occupies_capacity"] = task.occupies_capacity.into();
        if let Some(category) = &task.category_tag {
            payload["category_tag"] = category.clone().into();
            // Core requires category_tag to be an exact member of tags.
            let mut tags = payload["tags"].as_array().cloned().unwrap_or_default();
            if !tags.iter().any(|tag| tag.as_str() == Some(category)) {
                tags.push(category.clone().into());
            }
            payload["tags"] = tags.into();
        } else {
            payload.as_object_mut().unwrap().remove("category_tag");
        }
        let typed: Task = serde_json::from_value(payload.clone()).map_err(internal)?;
        typed.validate().map_err(internal)?;
        let changed = previous.is_none_or(|(_, old)| old != &payload);
        if changed {
            let (version, observed_version, created_at, compartment_label) =
                if let Some((row, _)) = previous {
                    let version = row
                        .version
                        .checked_add(1)
                        .ok_or_else(|| internal("Calendar Task version exhausted"))?;
                    (
                        version,
                        VersionRef::Version(u64::try_from(row.version).map_err(internal)?),
                        row.created_at.clone(),
                        row.compartment_label.clone(),
                    )
                } else {
                    (
                        1,
                        VersionRef::Absent,
                        now.to_string(),
                        "user-capture".into(),
                    )
                };
            let envelope = state.envelope_for(
                [(id.clone(), observed_version)].into_iter().collect(),
                AuthoritySource::User,
                now,
            )?;
            queries::admit_object(
                pool,
                &envelope,
                NewObjectRecord {
                    id: id.to_string(),
                    object_type: ObjectType::Task.as_str().into(),
                    version,
                    status: "active".into(),
                    compartment_label,
                    payload,
                    created_at,
                    updated_at: now.to_string(),
                },
            )
            .await?;
        }
        if previous.is_none() {
            response.captured += 1;
        } else if changed {
            // A gesture on the same event was counted as its update already.
            if !interaction.changed_external_ids.contains(&task.origin_event_id) {
                response.updated += 1;
            }
        } else {
            response.unchanged += 1;
        }
        // Only an event UbU can own enters the applied record. An unowned one stays
        // foreign to reconciliation and is read afresh by every capture: its
        // occupancy is a Task, never a claim that UbU applied the event.
        if not_ownable_diagnostic(&task.origin_event_id).is_some() {
            continue;
        }
        let mut origin = foreign
            .iter()
            .find(|event| event.external_id == task.origin_event_id)
            .unwrap()
            .clone();
        origin.task_id = id.to_string();
        origin.start_at = task.start_at;
        origin.end_at = task.end_at;
        // An event already in the applied record is replaced, not listed twice.
        applied.retain(|old| old.external_id != origin.external_id);
        applied.push(origin);
        recorded = true;
    }
    if recorded {
        applied.sort_by(|a, b| a.external_id.cmp(&b.external_id));
        calendar_apply::persist_result(
            pool,
            &StoredCalendarResult {
                schema_version: CALENDAR_PROJECTION_RESULT_SCHEMA_VERSION.into(),
                preview_id: UbuId::new(ObjectType::ProjectionPreview).to_string(),
                status: ProjectionResultStatus::Applied,
                applied_events: applied,
                operation_results: Vec::new(),
                diagnostics: Vec::new(),
            },
            now,
        )
        .await?;
    }
    response.diagnostics = diagnostics;
    Ok(response)
}

pub async fn capture(
    state: &AppState,
    mode: CalendarExportMode,
) -> Result<CalendarCaptureResponse> {
    mode.ensure_available(state)?;
    let _guard = state.inner().calendar_projection_lock.lock().await;
    let pool = state.inner().store.pool();
    let mut applied = calendar_apply::last_applied_events(pool).await?;
    let range = CalendarTimeRange::planning(state).await?;
    // One read includes recent owned events for completion/reopen. Foreign
    // capture still uses the original planning horizon, never this lookback.
    let mut observation_range = range.clone();
    let lookback = crate::planning_time::timestamp_at(u64::try_from(state.planning_now().inner().unix_timestamp()).map_err(internal)?.saturating_sub(86_400))?;
    observation_range.start = observation_range.start.min(ubu_core::UbuTimestamp::parse(&lookback).map_err(internal)?);
    let client: Arc<dyn CalendarApi> = if mode == CalendarExportMode::Live {
        Arc::new(GoogleCalendarApi::new(&state.inner().config).map_err(internal)?)
    } else {
        state.mock_calendar_api(&applied)
    };
    let mut observed = client
        .list_events(&observation_range)
        .await
        .map_err(AppError::Upstream)?;
    normalize_observed(&mut observed, &applied);
    observed.retain(|event| range.overlaps(event) || applied.iter().any(|old| old.external_id == event.external_id));
    let mut diagnostics = client.take_diagnostics().await;
    for event in &mut observed {
        let (description, diagnostic) = super::calendar_wire::capture_description(&event.external_id, event.description.as_deref());
        event.description = description;
        diagnostics.extend(diagnostic.map(super::calendar_wire::list_diagnostic));
    }
    let wire_skipped = diagnostics.iter().filter(|d| d.code != super::calendar_wire::DESCRIPTION_TOO_LARGE_CODE).count();
    // Which of the listed events UbU minted, by the stamp an insert writes. Drained
    // after the list, as the diagnostics are.
    let ubu_created_ids = client.take_ubu_created_ids().await;
    // An event that gained or lost its colour since UbU last saw it. Read here,
    // before a gesture accepts the whole observation into the applied record.
    let colour_flipped: BTreeSet<String> = observed
        .iter()
        .filter(|event| applied.iter().any(|old| old.external_id == event.external_id && old.color_id.is_some() != event.color_id.is_some()))
        .map(|event| event.external_id.clone())
        .collect();
    let interaction = super::calendar_interaction::apply(state, &observed, &mut applied).await?;
    diagnostics.extend(interaction.diagnostics);
    let conflicts =
        calendar_reconcile::classify(&applied, &observed, &known_external_ids(pool).await?, &ubu_created_ids);
    let foreign_ids: BTreeSet<_> = conflicts
        .iter()
        .filter(|c| c.conflict_type == "foreign")
        .map(|c| c.external_id.as_str())
        .collect();
    let existing = calendar_sources::by_source(pool).await?;
    // A captured Task follows its event's colour for as long as the event exists.
    // Such an event is in the applied record, so it is not foreign and is not
    // captured again. But when it gains or loses its colour the same rule decides
    // its placement afresh: the Task becomes Static or Dynamic, and is not left as
    // drift. Only a Task that capture made is read this way. An event UbU exported
    // for a Task of its own is never offered here: its colour is a gesture, and
    // means done.
    let replaced: BTreeSet<&str> = colour_flipped
        .iter()
        .filter(|id| !foreign_ids.contains(id.as_str()))
        .filter(|id| existing.get(*id).is_some_and(|(row, _)| row.status == "active"))
        .map(String::as_str)
        .collect();
    let foreign: Vec<_> = observed
        .iter()
        .filter(|e| foreign_ids.contains(e.external_id.as_str()) || replaced.contains(e.external_id.as_str()))
        .cloned()
        .collect();
    let by_source = existing
        .iter()
        .map(|(source, (row, _))| (source.clone(), row.id.clone()))
        .collect();
    let (tasks, plan_diagnostics) = plan_capture(
        &foreign,
        &crate::category_palette::CategoryPalette::from_pool(pool).await?.inverse(),
        &by_source,
        &ubu_created_ids,
    );
    // Every candidate that became no Task: the unusable ones, and UbU's own stale
    // exports, which are skipped on purpose.
    let not_captured = foreign
        .iter()
        .map(|e| &e.external_id)
        .collect::<BTreeSet<_>>()
        .len()
        - tasks.len();
    let mut response = CalendarCaptureResponse {
        schema_version: CALENDAR_CAPTURE_SCHEMA_VERSION.into(),
        captured: 0,
        updated: interaction.changed_external_ids.len(),
        moved: interaction.moved,
        resized: interaction.resized,

        GoogleCalendarApi::new(&state.inner().config).map_err(internal)?,
    ))
} else {
    None
};
let client: Arc<dyn CalendarApi> = match &google {
    Some(client) => client.clone(),
    None => state.mock_calendar_api(&applied),
};
let range = super::calendar_range::CalendarTimeRange::planning(state).await?;
let (applied, out_of_range_events): (Vec<_>, Vec<_>) = applied.into_iter().partition(|event| range.overlaps(event));
let mut observed = client.list_events(&range).await.map_err(AppError::Upstream)?;
super::calendar_capture::normalize_observed(&mut observed, &applied);
let ubu_created_ids = client.take_ubu_created_ids().await;
